source='''from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    counts = {3: 0, 1: 0}
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2 or (r, c) in seen:
                continue
            seen.add((r, c))
            queue = deque([(r, c)])
            cells = []
            while queue:
                x, y = queue.popleft()
                cells.append((x, y))
                for nx, ny in ((x-1, y), (x+1, y), (x, y-1), (x, y+1)):
                    if 0 <= nx < h and 0 <= ny < w and grid[nx][ny] == 2 and (nx, ny) not in seen:
                        seen.add((nx, ny))
                        queue.append((nx, ny))
            top = min(x for x, y in cells)
            bottom = max(x for x, y in cells)
            if len(cells) == 4 and sum(x == top for x, y in cells) == 1 and sum(x == bottom for x, y in cells) == 3:
                counts[3] += 1
            elif len(cells) == 4 and sum(x == top for x, y in cells) == 3 and sum(x == bottom for x, y in cells) == 1:
                counts[1] += 1
            else:
                raise ValueError(f"Unexpected component: {cells}")
    result = [[0] * 6 for _ in range(3)]
    slots = ((0, 0), (0, 2), (2, 0), (2, 2))
    for color, offset in ((3, 0), (1, 3)):
        for r, c in slots[:counts[color]]:
            result[r][c + offset] = color
    return result
'''
